<script setup>
import { useCustomerPresentation } from '../../Composables/customerPresentation';
const { customerText } = useCustomerPresentation();
import {Head,Link,useForm,usePage} from '@inertiajs/vue3';import {computed,ref} from 'vue';import TurnstileWidget from '../../Components/TurnstileWidget.vue';
import GoogleMark from '../../Components/GoogleMark.vue';import CustomerShell from '../../Components/CustomerShell.vue';const page=usePage(),turnstile=ref(null),security=computed(()=>page.props.security||{}),form=useForm({name:'',email:'',phone:'',password:'',password_confirmation:'',turnstile_token:''});const submit=()=>{if(form.processing)return;form.post('/register',{onFinish:()=>{form.reset('password','password_confirmation');form.turnstile_token='';turnstile.value?.reset()}})};</script>
<template><Head :title="customerText('pages.auth.register.attribute.title.5e0b087f', 'Daftar')"/><CustomerShell compact-footer><main class="lf-auth-wrap"><form class="lf-auth-card" @submit.prevent="submit"><p class="lf-eyebrow">{{ customerText("pages.auth.register.71ab59b4", "Buat akun") }}</p><h1>{{ customerText("pages.auth.register.320d3706", "Daftar LFAMILIA") }}</h1><p>{{ customerText("pages.auth.register.c9cff19d", "Buat akun untuk saldo, riwayat pesanan, membership, dan layanan pelanggan.") }}</p><p v-if="page.props.errors?.google" role="alert" class="mb-3 text-xs text-red-300">{{page.props.errors.google}}</p><div class="grid gap-3"><label v-for="x in [{k:'name',l:'Nama',t:'text',a:'name',p:'Masukkan nama'},{k:'email',l:'Email',t:'email',a:'email',p:'Masukkan email'},{k:'phone',l:'Nomor WhatsApp',t:'tel',a:'tel',p:'Contoh: 081234567890'}]" :key="x.k" class="text-[10px] font-semibold text-white/70">{{x.l}}<input v-model="form[x.k]" :type="x.t" :name="x.k" :autocomplete="x.a" :placeholder="x.p" :aria-invalid="Boolean(form.errors[x.k])" required><span v-if="form.errors[x.k]" role="alert" class="block mt-1 text-red-300">{{form.errors[x.k]}}</span></label><label class="text-[10px] font-semibold text-white/70">{{ customerText("pages.auth.register.1b5da681", "Kata sandi (minimal 12 karakter)") }}<input v-model="form.password" type="password" name="password" autocomplete="new-password" minlength="12" :placeholder="customerText('pages.auth.register.attribute.placeholder.d3d2f4b0', 'Minimal 12 karakter')" :aria-invalid="Boolean(form.errors.password)" required><span v-if="form.errors.password" role="alert" class="block mt-1 text-red-300">{{form.errors.password}}</span></label><label class="text-[10px] font-semibold text-white/70">{{ customerText("pages.auth.register.9c34c763", "Ulangi kata sandi") }}<input v-model="form.password_confirmation" type="password" name="password_confirmation" autocomplete="new-password" :placeholder="customerText('pages.auth.register.attribute.placeholder.7cd33da1', 'Masukkan ulang kata sandi')" :aria-invalid="Boolean(form.errors.password_confirmation)" required><span v-if="form.errors.password_confirmation" role="alert" class="block mt-1 text-red-300">{{form.errors.password_confirmation}}</span></label><TurnstileWidget v-if="security.turnstile_required" ref="turnstile" :site-key="security.turnstile_site_key" :action="security.turnstile_action" @token="form.turnstile_token=$event"/><p v-if="form.errors.turnstile_token" role="alert" class="text-xs text-red-300">{{form.errors.turnstile_token}}</p><button type="submit" class="lf-primary w-full" :disabled="form.processing">{{form.processing?'Memproses…':'Daftar'}}</button><a href="/auth/google/redirect" class="lf-secondary w-full gap-3" aria-label="Daftar dengan Google"><GoogleMark />{{ customerText("pages.auth.register.497d73c5", "Daftar dengan Google") }}</a></div><div class="lf-auth-links justify-end"><Link href="/login">{{ customerText("pages.auth.register.13c04f80", "Sudah punya akun? Masuk") }}</Link></div></form></main></CustomerShell></template>